function changeColor() {

  c = sin(radians(count))+1;
  d = sin(radians(count+60))+1;
  e = sin(radians(count+120))+1;
  c = map(c,0,1,0,255);
  d = map(d,0,1,0,255);
  e = map(e,0,1,0,255);
  println(c,d,e);
  stroke(c,d,220);
