//  }
}
function paint() {
  for (let x=0; x<width; x=x+1) {
    myPerlin = noise(float(x)/200,count/200);
    let myY = map(myPerlin, 0, 1, 0, height-mapHeight);
    line(x, myY, x,height );
  }

}

function changePerlin() {
